-- Stackademy's back office: generated by scripts/generate_backoffice.py. Don't edit it: change the script,
-- run it, and commit both. Compatible with MariaDB 10.6+ / 11.x and MySQL 8.x. Every name, number and
-- address in it is fictional. Fiscal year 2025, as of 2025-12-31.

USE `stackademy`;
/*!40101 SET NAMES utf8mb4 */;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `departments`;
CREATE TABLE `departments` (
  `department_id` int NOT NULL,
  `code` varchar(8) NOT NULL,
  `name` varchar(64) NOT NULL,
  `head_employee_id` int DEFAULT NULL,
  PRIMARY KEY (`department_id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `employees`;
CREATE TABLE `employees` (
  `employee_id` int NOT NULL,
  `employee_number` varchar(8) NOT NULL,
  `first_name` varchar(32) NOT NULL,
  `last_name` varchar(32) NOT NULL,
  `email` varchar(96) NOT NULL,
  `department_id` int NOT NULL,
  `title` varchar(64) NOT NULL,
  `manager_id` int DEFAULT NULL,
  `hire_date` date NOT NULL,
  `employment_type` varchar(16) NOT NULL,
  `location` varchar(32) NOT NULL,
  PRIMARY KEY (`employee_id`),
  UNIQUE KEY `employee_number` (`employee_number`),
  UNIQUE KEY `email` (`email`),
  KEY `department_id` (`department_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `compensation`;
CREATE TABLE `compensation` (
  `employee_id` int NOT NULL,
  `effective_date` date NOT NULL,
  `annual_salary` decimal(10,2) NOT NULL,
  `currency` char(3) NOT NULL,
  `pay_band` char(1) NOT NULL,
  `bonus_target_percent` int NOT NULL,
  PRIMARY KEY (`employee_id`, `effective_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pto_balances`;
CREATE TABLE `pto_balances` (
  `employee_id` int NOT NULL,
  `year` int NOT NULL,
  `accrued_days` decimal(5,1) NOT NULL,
  `used_days` decimal(5,1) NOT NULL,
  `carried_over_days` decimal(5,1) NOT NULL,
  PRIMARY KEY (`employee_id`, `year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `pto_requests`;
CREATE TABLE `pto_requests` (
  `request_id` int NOT NULL,
  `employee_id` int NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `days` int NOT NULL,
  `kind` varchar(16) NOT NULL,
  `status` varchar(16) NOT NULL,
  `approver_id` int DEFAULT NULL,
  PRIMARY KEY (`request_id`),
  KEY `employee_id` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `job_requisitions`;
CREATE TABLE `job_requisitions` (
  `requisition_id` int NOT NULL,
  `department_id` int NOT NULL,
  `title` varchar(64) NOT NULL,
  `hiring_manager_id` int NOT NULL,
  `opened_on` date NOT NULL,
  `closed_on` date DEFAULT NULL,
  `status` varchar(16) NOT NULL,
  `salary_min` decimal(10,2) NOT NULL,
  `salary_max` decimal(10,2) NOT NULL,
  `applicants` int NOT NULL,
  PRIMARY KEY (`requisition_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `students`;
CREATE TABLE `students` (
  `student_id` int NOT NULL,
  `first_name` varchar(32) NOT NULL,
  `last_name` varchar(32) NOT NULL,
  `email` varchar(96) NOT NULL,
  `country` char(2) NOT NULL,
  `signup_date` date NOT NULL,
  PRIMARY KEY (`student_id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `promo_codes`;
CREATE TABLE `promo_codes` (
  `code` varchar(16) NOT NULL,
  `percent_off` int NOT NULL,
  `valid_from` date NOT NULL,
  `valid_to` date NOT NULL,
  PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cohorts`;
CREATE TABLE `cohorts` (
  `cohort_id` int NOT NULL,
  `course_id` int NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `instructor_id` int NOT NULL,
  `delivery` varchar(16) NOT NULL,
  `capacity` int NOT NULL,
  PRIMARY KEY (`cohort_id`),
  KEY `course_id` (`course_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `enrollments`;
CREATE TABLE `enrollments` (
  `enrollment_id` int NOT NULL,
  `student_id` int NOT NULL,
  `cohort_id` int NOT NULL,
  `enrolled_on` date NOT NULL,
  `list_price` decimal(8,2) NOT NULL,
  `promo_code` varchar(16) DEFAULT NULL,
  `price_paid` decimal(8,2) NOT NULL,
  `status` varchar(16) NOT NULL,
  PRIMARY KEY (`enrollment_id`),
  KEY `student_id` (`student_id`),
  KEY `cohort_id` (`cohort_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `payments`;
CREATE TABLE `payments` (
  `payment_id` int NOT NULL,
  `enrollment_id` int NOT NULL,
  `paid_on` date NOT NULL,
  `amount` decimal(8,2) NOT NULL,
  `method` varchar(16) NOT NULL,
  PRIMARY KEY (`payment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `refunds`;
CREATE TABLE `refunds` (
  `refund_id` int NOT NULL,
  `payment_id` int NOT NULL,
  `refunded_on` date NOT NULL,
  `amount` decimal(8,2) NOT NULL,
  `reason` varchar(64) NOT NULL,
  PRIMARY KEY (`refund_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `corporate_contracts`;
CREATE TABLE `corporate_contracts` (
  `contract_id` int NOT NULL,
  `client_name` varchar(64) NOT NULL,
  `seats` int NOT NULL,
  `annual_value` decimal(10,2) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `account_manager_id` int NOT NULL,
  PRIMARY KEY (`contract_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ar_invoices`;
CREATE TABLE `ar_invoices` (
  `invoice_id` int NOT NULL,
  `contract_id` int NOT NULL,
  `invoice_number` varchar(32) NOT NULL,
  `invoice_date` date NOT NULL,
  `due_date` date NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `status` varchar(16) NOT NULL,
  `paid_on` date DEFAULT NULL,
  PRIMARY KEY (`invoice_id`),
  KEY `contract_id` (`contract_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `course_modules`;
CREATE TABLE `course_modules` (
  `module_id` int NOT NULL,
  `course_id` int NOT NULL,
  `sequence` int NOT NULL,
  `title` varchar(96) NOT NULL,
  PRIMARY KEY (`module_id`),
  KEY `course_id` (`course_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `lessons`;
CREATE TABLE `lessons` (
  `lesson_id` int NOT NULL,
  `module_id` int NOT NULL,
  `sequence` int NOT NULL,
  `title` varchar(128) NOT NULL,
  `duration_minutes` int NOT NULL,
  `status` varchar(16) NOT NULL,
  PRIMARY KEY (`lesson_id`),
  KEY `module_id` (`module_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `assets`;
CREATE TABLE `assets` (
  `asset_id` int NOT NULL,
  `lesson_id` int NOT NULL,
  `asset_type` varchar(16) NOT NULL,
  `status` varchar(16) NOT NULL,
  PRIMARY KEY (`asset_id`),
  KEY `lesson_id` (`lesson_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `vendors`;
CREATE TABLE `vendors` (
  `vendor_id` int NOT NULL,
  `name` varchar(64) NOT NULL,
  `category` varchar(32) NOT NULL,
  `payment_terms_days` int NOT NULL,
  `is_content_freelancer` tinyint(1) NOT NULL,
  PRIMARY KEY (`vendor_id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `production_tasks`;
CREATE TABLE `production_tasks` (
  `task_id` int NOT NULL,
  `asset_id` int NOT NULL,
  `task_type` varchar(16) NOT NULL,
  `vendor_id` int DEFAULT NULL,
  `employee_id` int DEFAULT NULL,
  `status` varchar(16) NOT NULL,
  `due_date` date NOT NULL,
  `cost_estimate` decimal(8,2) NOT NULL,
  PRIMARY KEY (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `chart_of_accounts`;
CREATE TABLE `chart_of_accounts` (
  `gl_account` char(4) NOT NULL,
  `name` varchar(64) NOT NULL,
  `account_type` varchar(16) NOT NULL,
  PRIMARY KEY (`gl_account`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `ap_invoices`;
CREATE TABLE `ap_invoices` (
  `invoice_id` int NOT NULL,
  `vendor_id` int NOT NULL,
  `invoice_number` varchar(32) NOT NULL,
  `invoice_date` date NOT NULL,
  `due_date` date NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `gl_account` char(4) NOT NULL,
  `department_id` int NOT NULL,
  `description` varchar(128) NOT NULL,
  `status` varchar(16) NOT NULL,
  `paid_on` date DEFAULT NULL,
  PRIMARY KEY (`invoice_id`),
  KEY `vendor_id` (`vendor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `expense_reports`;
CREATE TABLE `expense_reports` (
  `report_id` int NOT NULL,
  `employee_id` int NOT NULL,
  `submitted_on` date NOT NULL,
  `category` varchar(16) NOT NULL,
  `amount` decimal(8,2) NOT NULL,
  `status` varchar(16) NOT NULL,
  `approved_by` int DEFAULT NULL,
  PRIMARY KEY (`report_id`),
  KEY `employee_id` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `department_budgets`;
CREATE TABLE `department_budgets` (
  `department_id` int NOT NULL,
  `fiscal_year` int NOT NULL,
  `fiscal_month` int NOT NULL,
  `gl_account` char(4) NOT NULL,
  `budget_amount` decimal(10,2) NOT NULL,
  PRIMARY KEY (`department_id`, `fiscal_year`, `fiscal_month`, `gl_account`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `gl_entries`;
CREATE TABLE `gl_entries` (
  `line_id` int NOT NULL,
  `journal_id` int NOT NULL,
  `entry_date` date NOT NULL,
  `gl_account` char(4) NOT NULL,
  `department_id` int DEFAULT NULL,
  `description` varchar(64) NOT NULL,
  `source` varchar(16) NOT NULL,
  `debit` decimal(12,2) NOT NULL,
  `credit` decimal(12,2) NOT NULL,
  PRIMARY KEY (`line_id`),
  KEY `entry_date` (`entry_date`),
  KEY `gl_account` (`gl_account`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

